const townById = new Map(MYANMAR_TOWNS.map((town) => [town.id, town]));
const regionById = new Map(MYANMAR_REGIONS.map((region) => [region.id, region]));

export function isMyanmarTownId(id: string): boolean {
  return townById.has(id);
}

export function getMyanmarTownLabel(id: string, lang: 'my' | 'en' = 'my'): string {
  const town = townById.get(id);
  if (!town) return '';
  const region = regionById.get(town.regionId);
  return lang === 'my'
    ? `${town.local} (${town.en}) • ${town.townshipEn}${region ? ` • ${region.local}` : ''}`
    : `${town.en}, ${town.townshipEn}${region ? `, ${region.en}` : ''}`;
}
